// KnoxNet rack device library Ã¢â‚¬â€ real hardware catalog (2026 research pass).
// Generated from verified current vendor product lines. RU heights,
// power draw and weights cross-referenced from the NetBox
// devicetype-library where the model exists there; faceplates are
// auto-generated from the declarative schema below.
// NOTE: uHeight 0 = not rack-mountable (kept in catalog for reference).

export type RackCategory =
  | "switch"
  | "router"
  | "patch"
  | "nvr"
  | "server"
  | "ups"
  | "pdu"
  | "kvm"
  | "audio"
  | "video"
  | "lighting"
  | "broadcast"
  | "wireless"
  | "passive"
  | "demarc"
  | "cameras"
  | "access";

export type LedKind = "power" | "status" | "link" | "alert";

export interface FaceplateLed {
  /** position as a percentage 0-100 along the U-row, left-to-right */
  x: number;
  y?: number; // 0-100 within row
  kind: LedKind;
  on?: boolean;
  size?: number; // px diameter override
}

export interface FaceplatePortGroup {
  /** start x % */
  x: number;
  y?: number;
  /** count of ports */
  count: number;
  /** rows when count > 12 typically split into 2 rows */
  rows?: number;
  /** color of ports (typical RJ45 = "amber"; SFP = "navy") */
  color?: "amber" | "navy" | "green" | "white" | "black";
  /** label rendered above the group (e.g. "1-24 PoE") */
  label?: string;
}

export interface FaceplateText {
  x: number;
  y?: number;
  text: string;
  size?: "xs" | "sm" | "md" | "lg";
  weight?: "regular" | "bold";
  color?: "ink" | "amber" | "muted";
}

export interface FaceplateBay {
  /** rectangular cutout (HDD bay, battery, breaker) */
  x: number;
  y?: number;
  w: number;
  h: number;
  /** label inside */
  label?: string;
  /** style hint */
  style?: "hdd" | "battery" | "breaker" | "outlet" | "vent";
}

export interface FaceplateBrand {
  x: number;
  y?: number;
  text: string;
  /** Accent vertical/horizontal bar color */
  accent?: string;
}

export interface Faceplate {
  /** Base color of the chassis */
  base: "black" | "graphite" | "white" | "silver" | "amber";
  brand?: FaceplateBrand;
  ports?: FaceplatePortGroup[];
  leds?: FaceplateLed[];
  texts?: FaceplateText[];
  bays?: FaceplateBay[];
  /** Show side mounting screws */
  screws?: boolean;
  /** Vent slot pattern across full width (NVRs / servers) */
  vents?: boolean;
}

export interface RackDeviceType {
  id: string;
  label: string; // friendly name
  manufacturer: string; // for display
  model: string; // model number
  category: RackCategory;
  /** Height in U; 1U Ã¢â€°Ë† 44.45 mm; 0 = not rack-mountable */
  uHeight: number;
  powerWatts: number;
  weightLbs: number;
  defaultCost: number;
  laborHours: number;
  /** Front-facing port count (for the schedule) */
  frontPorts?: number;
  /** Rear-facing port count */
  rearPorts?: number;
  faceplate: Faceplate;
  notes?: string;
}

